using System.Diagnostics;
using System.Text;
using PcTidy.Core;
using PcTidy.Core.Model;
using PcTidy.Features.Developer.Common;
using PcTidy.Features.Developer.Environment;
using PcTidy.Hosting;
using PcTidy.TestbedGen;

namespace PcTidy.Features.Developer.Tests;

/// <summary>
/// One fake PC per test under testbed\developer\, built with the real composition root in sandbox mode (real
/// SafetyGuard, Executor and Undo). Either generated by TestbedBuilder or hand-made. Deleted afterwards.
/// </summary>
internal sealed class DevSandbox : IDisposable
{
    public static readonly string TestbedRoot = Path.Combine(FindCodeRoot(), "testbed", "developer");
    /// <summary>The testbed's "now": every generated file age is relative to it.</summary>
    public static readonly DateTime Anchor = new(2026, 11, 10, 12, 0, 0, DateTimeKind.Utc);

    private readonly bool _generated;

    public DevSandbox(string name, SandboxProfile? profile = null, bool generate = false, Action<AppSettings>? configure = null)
    {
        Profile = profile ?? SandboxProfile.Default;
        Root = Path.Combine(TestbedRoot, $"{name}-{Guid.NewGuid().ToString("N")[..6]}");
        _generated = generate;
        if (generate) TestbedBuilder.Generate(Root, TestbedSize.Small, Profile, new TestbedOptions { AnchorUtc = Anchor });
        else Directory.CreateDirectory(Root);
        Host = PcTidyHost.CreateSandbox(Root, Profile, configure);
        K = (SandboxKnownLocations)Host.Locations;
        Directory.CreateDirectory(K.UserProfile);
    }

    public string Root { get; }
    public SandboxProfile Profile { get; }
    public PcTidyHost Host { get; }
    public SandboxKnownLocations K { get; }

    /// <summary>"Now" for the scanners (default: well after everything in a hand-made sandbox).</summary>
    public DateTime Now { get; set; } = Anchor;
    public FakeDevEnvironment Environment { get; } = new();
    public IInUseChecker? InUse { get; set; }
    public Dictionary<string, object> ExtraOptions { get; } = new();

    public string Repos => Path.Combine(K.UserProfile, "source", "repos");

    public ScanContext Context(IReadOnlyList<string>? roots = null, ISafetyGuard? guard = null, IReadOnlySet<string>? running = null)
    {
        var c = Host.CreateScanContext(ScanDepth.Quick, roots);
        var options = new Dictionary<string, object>
        {
            [DeveloperOptions.Clock] = new FixedClock(Now),
            [DeveloperOptions.Environment] = Environment,
        };
        foreach (var (k, v) in ExtraOptions) options[k] = v;
        return new ScanContext
        {
            Locations = c.Locations, Safety = guard ?? c.Safety, InUse = InUse ?? c.InUse, Settings = c.Settings, Walker = c.Walker,
            Depth = c.Depth, Roots = roots, System = c.System, RunningProcesses = running ?? new HashSet<string>(), Options = options,
        };
    }

    public string Put(string path, string text, DateTime? writtenUtc = null) => Put(path, Encoding.UTF8.GetBytes(text), writtenUtc);

    public string Put(string path, byte[] bytes, DateTime? writtenUtc = null)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllBytes(path, bytes);
        var w = writtenUtc ?? Now.AddDays(-200);
        File.SetCreationTimeUtc(path, w);
        File.SetLastWriteTimeUtc(path, w);
        return path;
    }

    /// <summary>A project folder with a .git (activity files dated <paramref name="gitAgeDays"/> ago) and a source file.</summary>
    public string Project(string name, double gitAgeDays = 200, string? parent = null)
    {
        var p = Path.Combine(parent ?? Repos, name);
        var at = Now.AddDays(-gitAgeDays);
        Put(Path.Combine(p, ".git", "HEAD"), "ref: refs/heads/main\n", at);
        Put(Path.Combine(p, ".git", "index"), "DIRC", at);
        Put(Path.Combine(p, ".git", "logs", "HEAD"), "0000 1111 commit\n", at);
        Put(Path.Combine(p, "README.md"), "# " + name + "\n", at);
        return p;
    }

    /// <summary>Makes a directory junction (needs no admin rights). False if this PC can't make one.</summary>
    public static bool TryJunction(string link, string target)
    {
        try
        {
            using var p = Process.Start(new ProcessStartInfo("cmd.exe", $"/c mklink /J \"{link}\" \"{target}\"")
            {
                CreateNoWindow = true, UseShellExecute = false, RedirectStandardOutput = true, RedirectStandardError = true,
            })!;
            p.WaitForExit(10_000);
            return Directory.Exists(link) && (File.GetAttributes(link) & FileAttributes.ReparsePoint) != 0;
        }
        catch (Exception ex) when (ex is System.ComponentModel.Win32Exception or IOException) { return false; }
    }

    public void Dispose()
    {
        Host.Dispose();
        try
        {
            if (_generated) TestbedBuilder.Delete(Root);
            else DeleteTree(Root);
        }
        catch (Exception) { /* best effort; the next run uses a fresh folder name */ }
    }

    /// <summary>Deletes a hand-made sandbox without following junctions (a junction is removed, never its target).</summary>
    private static void DeleteTree(string dir)
    {
        if (!Directory.Exists(dir)) return;
        foreach (var entry in new DirectoryInfo(dir).EnumerateFileSystemInfos())
        {
            var isLink = (entry.Attributes & FileAttributes.ReparsePoint) != 0;
            if (entry is DirectoryInfo d && !isLink) { DeleteTree(d.FullName); continue; }
            if (entry is FileInfo) entry.Attributes = FileAttributes.Normal;
            entry.Delete(); // a junction is removed as a link; its target is left alone
        }
        File.SetAttributes(dir, FileAttributes.Normal);
        Directory.Delete(dir, false);
    }

    private static string FindCodeRoot()
    {
        var d = new DirectoryInfo(AppContext.BaseDirectory);
        while (d != null && !File.Exists(Path.Combine(d.FullName, "PcTidy.sln"))) d = d.Parent;
        return d?.FullName ?? throw new InvalidOperationException("PcTidy.sln not found above " + AppContext.BaseDirectory);
    }
}

internal sealed class FixedClock(DateTime utc) : TimeProvider
{
    public override DateTimeOffset GetUtcNow() => new(DateTime.SpecifyKind(utc, DateTimeKind.Utc));
}

/// <summary>Test double for PATH, variables, WSL and Docker.</summary>
internal sealed class FakeDevEnvironment : IDevEnvironment
{
    public List<string> Path { get; } = new();
    public Dictionary<string, string> Variables { get; } = new(StringComparer.OrdinalIgnoreCase);
    public List<WslDistro> Distros { get; } = new();
    public string? DockerJson { get; set; }

    public IReadOnlyList<string> SearchPath() => Path;
    public string? Variable(string name) => Variables.TryGetValue(name, out var v) ? v : null;
    public IReadOnlyList<WslDistro> WslDistros() => Distros;
    /// <summary>Default: a current WSL package; null = only Windows' built-in WSL.</summary>
    public Version? WslVersion { get; set; } = new(2, 3, 26);
    public Version? WslPackageVersion() => WslVersion;
    public Task<string?> DockerDiskUsageJsonAsync(CancellationToken ct) => Task.FromResult(DockerJson);
}

/// <summary>Reports chosen folders as in use by a named app.</summary>
internal sealed class FakeInUse(string app, params string[] busy) : IInUseChecker
{
    public Task<IReadOnlyList<InUseInfo>> CheckAsync(IReadOnlyList<string> paths, CancellationToken ct)
        => Task.FromResult<IReadOnlyList<InUseInfo>>(paths.Select(p =>
        {
            var inUse = busy.Any(b => PathUtil.IsUnder(b, p) || PathUtil.IsUnder(p, b));
            return new InUseInfo(p, inUse, inUse ? new[] { app } : Array.Empty<string>());
        }).ToList());

    public bool IsLocked(string path) => false;
}
